nextflow_process {

    name "Test Process QCATCH"
    script "../main.nf"
    process "QCATCH"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "qcatch"

    test("test_qcatch - 1k_pbmc_v3") {

        def quant_dir
        setup {
            // the URL has no extension, so name the compression
            quant_dir = extract('https://umd.box.com/shared/static/zd4sai70uw9fs24e1qx6r41ec50pf45g.zip', compression: 'zip').resolve('test_data/1k_pbmc_v3')
        }

        when {
            process {
                """
                input[0] = [[id:'1k_pbmc_v3'], '10X_3p_v3', file('${quant_dir}')]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                // Report embeds UMAP coordinates, which vary with the platform's numerical libraries
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["report"])).match() },
                { assert path(process.out.report[0][1]).text.contains('Number of retained cells') }
            )
        }
    }

    test("test_qcatch - remove_doublets") {

        config "./nextflow_doublets.config"

        def quant_dir
        setup {
            // the URL has no extension, so name the compression
            quant_dir = extract('https://umd.box.com/shared/static/zd4sai70uw9fs24e1qx6r41ec50pf45g.zip', compression: 'zip').resolve('test_data/1k_pbmc_v3')
        }

        when {
            process {
                """
                input[0] = [[id:'1k_pbmc_v3_doublets'], '10X_3p_v3', file('${quant_dir}')]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.report.get(0).get(1)).size() > 0 },
                { assert path(process.out.filtered_h5ad.get(0).get(1)).size() > 0 },
                { assert path(process.out.metrics_summary.get(0).get(1)).size() > 0 },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith('versions') }).match("remove_doublets_versions") }
            )
        }
    }

    test("test_qcatch - stub") {
        options "-stub-run"

        when {
            process {
                """
                meta = [id:'test_stub']
                input[0] = Channel.of([meta, '10X_3p_v3', file('stub_quant_dir')])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

env {
    MPLCONFIGDIR        = "./tmp"
    NUMBA_CACHE_DIR     = "./tmp"
    NUMBA_DISABLE_CACHE = 1
}

process {
    withName: 'QCATCH' {
        ext.args = '--remove_doublets'
    }
}
